STORE = {}


def build_store():
    C = 'Store'
    rng = np.random.default_rng(21)
    mesh_obj('StoreFloor', [(-13, -6, 0), (13, -6, 0), (13, 33, 0), (-13, 33, 0)], [(0, 1, 2, 3)], MAT['storefloor'], C, smooth=False)
    bm = bmesh.new()
    add_box(bm, -13, 33, 0, 13, 33.3, 4.8)
    add_box(bm, -13.3, -4.5, 0, -13, 33, 4.8)
    add_box(bm, 13, -4.5, 0, 13.3, 33, 4.8)
    add_box(bm, -13, -4.8, 0, 13, -4.5, 0.45)
    add_box(bm, -13, -4.8, 3.2, 13, -4.5, 4.8)
    for x in np.arange(-12, 13, 4.0):
        add_box(bm, x - 0.2, -4.8, 0.45, x + 0.2, -4.5, 3.2)
    for x0, x1, y0, y1 in ((-13, 13, 32.95, 33.0), (-12.95, -12.9, -4.5, 33), (12.9, 12.95, -4.5, 33)):
        add_box(bm, x0, y0, 0.0, x1, y1, 0.5, mi=1)
