    mesh_obj('StoreCeiling', [(-13, -6, 4.8), (-13, 33, 4.8), (13, 33, 4.8), (13, -6, 4.8)], [(0, 1, 2, 3)], MAT['ceiling'], C, smooth=False)
    out = mesh_obj('StoreOutside', [(-14, -6.5, -1), (14, -6.5, -1), (14, -6.5, 6), (-14, -6.5, 6)], [(0, 1, 2, 3)], MAT['outside'], C, smooth=False)
    out.visible_shadow = False
    # ceiling light panels (seen) and area lights (light the room)
    bm = bmesh.new()
    for x in (-8.7, -4.9, 0.0, 4.9, 8.7):
        for y in np.arange(-2.5, 32, 3.5):
            add_box(bm, x - 0.25, y - 1.2, 4.55, x + 0.25, y + 1.2, 4.6)
    pan = obj_from_bm('StorePanels', bm, MAT['panel'], C)
    pan.visible_shadow = False
    STORE['lights'] = []
    for x in (-7.0, 0.0, 7.0):
        for y in (1.0, 11.0, 21.0, 30.0):
            STORE['lights'].append(area_light(f'S_area_{x}_{y}', (x, y, 4.4), (0, 0, 0), 4.0, 6.0, 380.0, (0.94, 0.98, 1.0), C))
    STORE['window'] = area_light('S_window', (0, -4.4, 1.9), (R(-90), 0, 0), 24.0, 2.6, 2600.0, (1.0, 0.82, 0.62), C)
    # gondolas with products
    levels = [0.12, 0.55, 0.95, 1.35, 1.75]
    bm = bmesh.new()
    G = [-10.6, -6.8, -3.0, 3.0, 6.8, 10.6]
    for x in G:
        gondola(bm, x, 7.0, 28.0, levels)
    obj_from_bm('Gondolas', bm, [MAT['shelf'], MAT['pegboard'], MAT['pricestrip']], C)
    pts, var, rot = [], [], []
    for x in G:
        for facing in (1, -1):
            xf = x + facing * 0.5
            for sy in np.arange(7.0, 28.0, 3.0):
                if x == -3.0 and facing == 1 and sy < 19:
                    kinds = [9]                                  # the bakery, facing the main aisle
                elif x == 3.0 and facing == -1:
                    kinds = [0, 1, 2, 3, 4]                       # cereal, facing the main aisle
                else:
                    kinds = [[0, 1, 2, 3, 4], [5, 6, 7, 8], [12, 13, 14], [5, 6], [0, 2, 4]][int(rng.integers(5))]
                for z in levels:
                    fill_shelf(pts, var, rot, xf, facing, sy, sy + 3.0, z, kinds, rng)
    gn_scatter('Products', pts, var, rot, np.ones((len(pts), 3)), COLL['ProdT'], C)
    # dairy fridge along the back wall (eggs x -12..-7, milk x -6.6..-1)
    bm = bmesh.new()
    add_box(bm, -12.6, 32.0, 0, -0.6, 33.0, 0.25, mi=0)
    add_box(bm, -12.6, 32.85, 0.25, -0.6, 33.0, 2.25, mi=1)
    add_box(bm, -12.6, 32.0, 2.1, -0.6, 33.0, 2.4, mi=0)
    for x in (-12.6, -6.8, -0.6):
        add_box(bm, x - 0.04, 32.0, 0, x + 0.04, 33.0, 2.4, mi=0)
    for z in (0.25, 0.65, 1.05, 1.45, 1.85):
        add_box(bm, -12.6, 32.05, z - 0.025, -0.6, 32.85, z, mi=1)
        add_box(bm, -12.6, 32.0, z - 0.06, -0.6, 32.05, z + 0.005, mi=2)
    obj_from_bm('Fridge', bm, [MAT['fridge'], MAT['fridge_in'], MAT['pricestrip']], C)
    fl = mesh_obj('FridgeLight', [(-12.6, 32.1, 2.08), (-0.6, 32.1, 2.08), (-0.6, 32.25, 2.08), (-12.6, 32.25, 2.08)], [(0, 3, 2, 1)],
                  MAT['fridge_light'], C, smooth=False)
    fl.visible_shadow = False
    STORE['fridge_light'] = area_light('S_fridge', (-6.6, 31.6, 2.3), (R(30), 0, 0), 12.0, 0.4, 300.0, (0.9, 0.96, 1.0), C)
    for name, x0, x1, kind in (('EggsFull', -12.5, -6.95, 11), ('Milk', -6.65, -0.7, 10)):
        pts, var, rot = [], [], []
        for z in (0.25, 0.65, 1.05, 1.45, 1.85):
            y = x0 + 0.03
            w = PROD_W[kind]
            while y + w < x1:
                for r in range(3):
                    pts.append((y + w / 2, 32.2 + r * 0.2, z))
                    var.append(kind)
                    rot.append((0, 0, R(180) + rng.normal(0, 0.03)))
                y += w + 0.015
        gn_scatter(name, pts, var, rot, np.ones((len(pts), 3)), COLL['ProdT'], C)
    # the last egg carton (struggle shot)
    pts = [(-9.6, 32.25, 1.45)]
    gn_scatter('EggLast', pts, [11], [(0, 0, R(180))], np.ones((1, 3)), COLL['ProdT'], C)
    card('LimitSign', MAT['limit'], 0.9, 0.45, (-9.6, 31.97, 2.62), yaw=0, collection=C)
    card('TagEggs', MAT['tag_eggs'], 0.16, 0.08, (-9.35, 31.985, 1.4), yaw=0, collection=C)
    # hero price tags: bread aisle (owner re-tags) and milk
    STORE['tags'] = {}
    for key, yy, z in (('buns', 9.3, 1.35), ('rye', 10.15, 0.55), ('bagel', 10.9, 1.35), ('bread', 11.75, 0.95)):
        for st in (0, 1):
            ob = card(f'Tag_{key}{st}', MAT[f'tag_{key}{st}'], 0.2, 0.1, (-2.48, yy, z - 0.02), yaw=90, collection=C)
            STORE['tags'][f'{key}{st}'] = ob
    for st in (0, 1):
        STORE['tags'][f'milk{st}'] = card(f'Tag_milk{st}', MAT[f'tag_milk{st}'], 0.24, 0.12, (-3.9, 31.985, 1.02), yaw=0, collection=C)
    # signs and banners
    card('Banner0', MAT['banner0'], 9.0, 1.4, (6.0, 32.94, 3.4), yaw=0, collection=C)
