    card('Sign_dairy', MAT['aisle_dairy'], 1.8, 0.6, (-6.6, 30.0, 3.4), yaw=0, collection=C)
    card('Sign_produce', MAT['aisle_produce'], 1.5, 0.5, (-8.7, 18.0, 3.4), yaw=0, collection=C)
    card('Sign_bikes', MAT['aisle_bikes'], 1.8, 0.6, (9.5, 4.2, 3.0), yaw=180, collection=C)
    card('Sign_checkout', MAT['aisle_checkout'], 2.0, 0.66, (2.0, 4.8, 3.6), yaw=180, collection=C)
    # checkouts: counters along Y at x0 .. x0+0.8, y 0.4 .. 3.4
