CITY = Vector((5000.0, 0.0, 0.0))
CITYD = {}
SCREEN = dict(c=Vector((0.0, 119.42, 26.0)), w=19.2, h=24.0)          # centre (city-local), size in metres


def Ct(x, y, z=0.0):
    return CITY + Vector((x, y, z))


def build_city():
    C = 'City'
    rng = np.random.default_rng(61)
    mesh_obj('CityRoad', [Ct(-7, -60, 0), Ct(7, -60, 0), Ct(7, 140, 0), Ct(-7, 140, 0)], [(0, 1, 2, 3)], MAT['asphalt'], C, smooth=False)
    bm = bmesh.new()
    for sx in (1, -1):
        add_box(bm, sx * 7.0 - 0.15, -60, 0, sx * 7.0 + 0.15, 140, 0.15)
        add_box(bm, min(sx * 7.15, sx * 11.0), -60, 0, max(sx * 7.15, sx * 11.0), 140, 0.12)
    for y in np.arange(-58, 138, 5.0):
        add_box(bm, -0.08, y, 0.0, 0.08, y + 2.5, 0.015, mi=1)
    for y in (40.0, 41.0, 42.0, 43.0, 44.0, 45.0):           # zebra crossing
        add_box(bm, -6.5, y, 0.0, 6.5, y + 0.5, 0.015, mi=1)
    obj_from_bm('CityKerbs', bm, [MAT['concrete'], MAT['white_paint']], C, loc=CITY)
    # buildings on both sides and across the end of the street
    facs = ['facade0', 'facade1', 'facade2', 'facade3']
    for sx in (1, -1):
        y = -60.0
        k = 0
        while y < 118:
            d = rng.uniform(16, 26)
            hgt = rng.uniform(22, 70)
            bm = bmesh.new()
            add_box(bm, 0, 0, 0, 22, d - 0.4, hgt)
            ob = obj_from_bm(f'Bld{sx}_{k}', bm, MAT[facs[int(rng.integers(4))]], C, loc=Ct(sx * 11.0 if sx > 0 else -33.0, y))
            k += 1
            y += d
    bm = bmesh.new()
    add_box(bm, -40, 120, 0, 40, 140, 58)
    obj_from_bm('BldEnd', bm, MAT['facade1'], C, loc=CITY)
    c, w, h = SCREEN['c'], SCREEN['w'], SCREEN['h']
    bm = bmesh.new()
    add_box(bm, -w / 2 - 0.6, 119.5, c.z - h / 2 - 0.6, w / 2 + 0.6, 120.0, c.z + h / 2 + 0.6)
    obj_from_bm('ScreenFrame', bm, MAT['darksteel'], C, loc=CITY)
    scr = card('Screen', MAT['screen'], w, h, Ct(c.x, c.y - 0.02, c.z), yaw=0, collection=C)
    CITYD['screen_light'] = area_light('C_screen', Ct(0, 117.0, c.z), (R(90), 0, 0), w, h, 0.0, (0.7, 1.0, 0.8), C)
    # shop signs on the ground floors
    for k, (name, x, y) in enumerate((('sign_bank', 11.0, 8.0), ('sign_trees', -11.0, 20.0), ('sign_cash', 11.0, 36.0),
                                      ('sign_seeds', -11.0, 55.0), ('sign_rent', 11.0, 72.0), ('sign_cash', -11.0, -6.0))):
        card(f'Shop{k}', MAT[name], 6.0, 1.5, Ct(x - 0.03 * (1 if x > 0 else -1), y, 4.6), yaw=-90 if x > 0 else 90, collection=C)
    # parked cars, street lamps
    paints = ['car_red', 'car_blue', 'car_white', 'car_yellow', 'car_black', 'car_green']
    for k, y in enumerate((-30, -18, -4, 12, 27, 50, 64, 82, 96)):
        car(f'CityCar{k}', C, Ct(5.6 if k % 2 else -5.6, y + rng.normal(0, 1.0), 0.0), 0 if k % 2 else 180, paints[k % 6])
    bm = bmesh.new()
    for y in np.arange(-50, 120, 22.0):
        for sx in (1, -1):
            add_capsule(bm, (sx * 7.6, y, 0), (sx * 7.6, y, 7.5), 0.09, 0.07, seg=8)
            add_capsule(bm, (sx * 7.6, y, 7.5), (sx * 6.2, y, 7.9), 0.06, seg=8)
    obj_from_bm('Lamps', bm, MAT['darksteel'], C, loc=CITY, smooth=True)
    # notes lying on the pavement
    cnt = 1500
    cxy = np.stack([rng.uniform(-10.5, 10.5, cnt), rng.uniform(-10, 115, cnt)], 1)
    z = np.where(np.abs(cxy[:, 0]) > 7.15, 0.13, 0.02) + rng.uniform(0, 0.01, cnt)
    yaw = rng.uniform(0, 6.3, cnt)
    U = np.stack([np.cos(yaw), np.sin(yaw), np.zeros(cnt)], 1)
    Vv = np.stack([-np.sin(yaw), np.cos(yaw), np.zeros(cnt)], 1)
    ob = quad_mesh('CityGroundBills', cnt, MAT['bill'], C)
    set_quads(ob, bill_quads(np.concatenate([cxy, z[:, None]], 1) + np.array(CITY), U, Vv))
    # the graph lines (rebuilt every frame in update_graph)
    CITYD['lines'] = [quad_mesh('GraphMoney', 120, MAT['led_green'], C), quad_mesh('GraphGoods', 120, MAT['led_orange'], C)]
    for ob in CITYD['lines']:
        ob.visible_shadow = False
    bm = bmesh.new()
    add_sphere(bm, 0.35, 12, 8)
    CITYD['heads'] = [obj_from_bm('GraphHeadM', bm, MAT['led_green'], C, smooth=True)]
    bm = bmesh.new()
    add_sphere(bm, 0.35, 12, 8)
    CITYD['heads'].append(obj_from_bm('GraphHeadG', bm, MAT['led_orange'], C, smooth=True))
    # sacks of cash for the walkers
    CITYD['sacks'] = []


def sack(name, collection):
    bm = bmesh.new()
    vs = add_ellipsoid(bm, (0, 0, 0), (0.24, 0.2, 0.3), 16, 12)
    for v in vs:
        if v.co.z > 0.18:
            v.co.x *= 0.45
            v.co.y *= 0.45
    add_capsule(bm, (0, 0, 0.27), (0, 0, 0.36), 0.05, 0.07, seg=8)
    return obj_from_bm(name, bm, MAT['sack'], collection, smooth=True)


def screen_px(px, py):
    """Graph pixel (on the 1024x1280 screen texture) -> city-local 3D point just in front of the screen."""
    c, w, h = SCREEN['c'], SCREEN['w'], SCREEN['h']
    return Vector((c.x - w / 2 + w * px / 1024.0, c.y - 0.08, c.z + h / 2 - h * py / 1280.0))


def update_graph(t):
    a, b = EV['graph']
    u = lin(t, a, b)
    x0, x1, y0, y1 = 120, 960, 300, 1130
    for k, ob in enumerate(CITYD['lines']):
        n = 120
        s = np.linspace(0, max(u, 1e-4), n + 1)
        if k == 0:
            val = 0.06 + 0.9 * (np.exp(3.2 * s) - 1) / (math.exp(3.2) - 1)       # MONEY: shoots up
        else:
            val = 0.06 + 0.1 * s + 0.012 * np.sin(s * 18)                          # GOODS: barely moves
        px = x0 + (x1 - x0) * s
        py = y1 - (y1 - y0) * val
        P = np.array([tuple(Ct(*screen_px(x, y))) for x, y in zip(px, py)])
        d = np.diff(P, axis=0)
        d /= np.linalg.norm(d, axis=1)[:, None] + 1e-9
        nrm = np.stack([np.zeros(n), np.zeros(n), np.ones(n)], 1)
        side = np.cross(d, np.array([0, -1.0, 0]))
        wdt = 0.16
        V = np.stack([P[:-1] - side * wdt, P[1:] - side * wdt, P[1:] + side * wdt, P[:-1] + side * wdt], 1)
        if u <= 0:
            V[:] = 0.0
        set_quads(ob, V)
        CITYD['heads'][k].location = P[-1] if u > 0 else Ct(0, 200, -50)


# ============================================================================
# Flying banknotes (one pool of quads, rebuilt every frame) and soft dust/mote billboards
# ============================================================================
NBILLS = 2600
BEMIT = {}            # shot name -> list of note emitters
FLY = {}


def bill_emitter(src, rate, life, t0=-10.0, t1=1e9, area=(0.3, 0.3, 0.1), v0=(0, 0, 0), vjit=0.3, fall=0.9, wind=(0, 0, 0),
                 tau=0.6, flutter=0.25, ffreq=3.0, spin=2.0, ground=-1e9, salt=0.0, scale=1.0, tumble=1.0):
    return dict(src=src, rate=rate, life=life, t0=t0, t1=t1, area=np.array(area, float), v0=np.array(v0, float), vjit=vjit,
                fall=fall, wind=np.array(wind, float), tau=tau, flutter=flutter, ffreq=ffreq, spin=spin, ground=ground,
                salt=salt, scale=scale, tumble=tumble)


def eval_bills(e, t):
    src = e['src']
    K = len(src) if not callable(src) else 1
    slots = int(math.ceil(e['life'] * e['rate'])) + 1
    k = np.repeat(np.arange(K), slots)
    j = np.tile(np.arange(slots), K)
    phase = hash01(k, 0.5, e['salt'])
    i = np.floor((t - e['t0']) * e['rate'] - phase) - j
    tb = e['t0'] + (i + phase) / e['rate']
    age = t - tb
    ok = (age >= 0) & (age <= e['life']) & (tb <= e['t1']) & (i >= 0)
    k, i, age, tb = k[ok], i[ok], age[ok], tb[ok]
    if len(k) == 0:
        return None
    r = [hash01(k + 0.1 * q, i, e['salt'] + q) for q in range(8)]
    if callable(src):
        start = np.array([tuple(src(x)) for x in tb]).reshape(-1, 3)
    else:
        start = np.asarray(src, float)[k]
    start = start + (np.stack(r[:3], 1) - 0.5) * 2 * e['area']
    dj = np.stack([r[3] - 0.5, r[4] - 0.5, r[5] - 0.5], 1)
    v0 = e['v0'] + dj * 2 * e['vjit']
    vt = e['wind'] + np.array([0, 0, -e['fall']])
    tau = e['tau']
    fa = r[6] * 2 * np.pi
    fdir = np.stack([np.cos(fa), np.sin(fa), np.zeros_like(fa)], 1)

    def pos(a):
        p = start + vt * a[:, None] + (v0 - vt) * (tau * (1 - np.exp(-a / tau)))[:, None]
        return p + fdir * (e['flutter'] * np.sin(e['ffreq'] * a + r[7] * 6.3) * np.clip(a / 0.4, 0, 1))[:, None]
    p = pos(age)
    landed = p[:, 2] < e['ground']
    if landed.any():
        lo, hi = np.zeros(landed.sum()), age[landed].copy()
        for _ in range(12):
            mid = (lo + hi) / 2
            zm = pos(mid)[:, 2] if False else (start[landed] + vt * mid[:, None] + (v0[landed] - vt) * (tau * (1 - np.exp(-mid / tau)))[:, None])[:, 2]
            above = zm > e['ground']
            lo = np.where(above, mid, lo)
            hi = np.where(above, hi, mid)
        pl = start[landed] + vt * hi[:, None] + (v0[landed] - vt) * (tau * (1 - np.exp(-hi / tau)))[:, None]
        pl[:, 2] = e['ground'] + 0.004 + r[0][landed] * 0.004
        p[landed] = pl
    sgn = np.where(r[1] > 0.5, 1.0, -1.0)
    yaw = r[2] * 6.3 + e['spin'] * age * sgn
    pitch = e['tumble'] * (0.9 * np.sin(e['ffreq'] * 1.3 * age + r[4] * 6.3) + 0.3)
    roll = e['tumble'] * 0.7 * np.sin(e['ffreq'] * 0.9 * age + r[5] * 6.3)
    pitch = np.where(landed, 0.0, pitch)
    roll = np.where(landed, 0.0, roll)
    cy, sy_, cp, sp, cr, sr = np.cos(yaw), np.sin(yaw), np.cos(pitch), np.sin(pitch), np.cos(roll), np.sin(roll)
    ux, uy, uz = cr, np.zeros_like(cr), -sr                       # Ry(roll) (1,0,0)
    uy, uz = uy * cp - uz * sp, uy * sp + uz * cp                 # Rx(pitch)
    U = np.stack([ux * cy - uy * sy_, ux * sy_ + uy * cy, uz], 1)
    vx, vy, vz = np.zeros_like(cr), cp, sp                        # Rx(pitch) (0,1,0)
    V = np.stack([vx * cy - vy * sy_, vx * sy_ + vy * cy, vz], 1)
    return p, U, V, np.full(len(p), e['scale'])


def update_bills(t, shot, cs, extra=()):
    groups = [eval_bills(e, t) for e in BEMIT.get(shot, []) if e['t0'] <= t]
    groups = [g for g in groups if g is not None] + [g for g in extra if g is not None]
    Vq = np.zeros((NBILLS, 4, 3))
    if groups:
        p, U, V, s = (np.concatenate(x) for x in zip(*groups))
        d = np.linalg.norm(p - np.array(cs['loc']), axis=1)
        front = (p - np.array(cs['loc'])) @ np.array(cs['fwd']) > 0.05
        p, U, V, s, d = p[front], U[front], V[front], s[front], d[front]
        if len(p) > NBILLS:
            idx = np.argsort(d)[:NBILLS]
            p, U, V, s = p[idx], U[idx], V[idx], s[idx]
        w, h = BILL[0] / 2 * s[:, None], BILL[1] / 2 * s[:, None]
        m = len(p)
        Vq[:m] = np.stack([p - U * w - V * h, p + U * w - V * h, p + U * w + V * h, p - U * w + V * h], 1)
    set_quads(FLY['bills'], Vq)


MAXQ = {'dust': 700, 'dot': 1200}
PART = {}
EMIT = {}


def billboard_obj(name, n, mat):
    faces = np.arange(4 * n).reshape(n, 4)
    ob = mesh_obj(name, np.zeros((4 * n, 3)), faces, mat, collection='FX', smooth=False,
                  uvs=np.tile(np.array([[0, 0], [1, 0], [1, 1], [0, 1]], np.float32), (n, 1)))
    ob.data.color_attributes.new('sm', 'FLOAT_COLOR', 'CORNER')
    ob.visible_shadow = False
    ob.visible_diffuse = False
    return ob


def emitter(kind, src, rate, life, vel, spread, size, opacity=1.0, glow=0.0, area=0.5, t0=-10.0, t1=1e9,
            rise=0.0, turb=0.4, salt=0.0):
    return dict(kind=kind, src=np.atleast_2d(np.array(src, float)), rate=rate, life=life, vel=np.array(vel, float),
                spread=spread, size=size, opacity=opacity, glow=glow, area=area, t0=t0, t1=t1, rise=rise, turb=turb, salt=salt)


def eval_emitter(e, t):
    K = len(e['src'])
    slots = int(math.ceil(e['life'] * e['rate'])) + 1
    k = np.repeat(np.arange(K), slots)
    j = np.tile(np.arange(slots), K)
    phase = hash01(k, 0.5, e['salt'])
    i = np.floor((t - e['t0']) * e['rate'] - phase) - j
    tb = e['t0'] + (i + phase) / e['rate']
    age = t - tb
    ok = (age >= 0) & (age <= e['life']) & (tb <= e['t1']) & (i >= 0)
    k, i, age = k[ok], i[ok], age[ok]
    r1, r2, r3, r4 = (hash01(k + 0.1 * q, i, e['salt'] + q) for q in range(4))
    a = r1 * 2 * np.pi
    rr = np.sqrt(r2) * e['area']
    start = e['src'][k] + np.stack([rr * np.cos(a), rr * np.sin(a), (r3 - 0.5) * e['area']], -1)
    dirn = np.stack([np.cos(a + 1.3), np.sin(a + 1.3), (r3 - 0.5) * 0.6], -1)
    u = age / e['life']
    pos = start + e['vel'][None, :] * age[:, None] + dirn * (e['spread'] * age)[:, None]
    pos[:, 2] += 0.5 * e['rise'] * age ** 2
    pos += e['turb'] * np.stack([np.sin(age * 1.3 + r4 * 6.3), np.cos(age * 1.1 + r1 * 6.3), 0.5 * np.sin(age * 0.9 + r2 * 6.3)], -1)
    s0, s1 = e['size']
    size = (s0 + (s1 - s0) * u ** 0.6) * (0.7 + 0.6 * r3)
    alpha = e['opacity'] * np.clip(u / 0.12, 0, 1) * np.clip((1 - u) / 0.45, 0, 1)
    return pos, size, u, r4, alpha, np.full_like(u, e['glow'])


def cam_basis(cs):
    fwd = Vector(cs['fwd']).normalized()
    right = fwd.cross(Vector((0, 0, 1)))
    if right.length < 1e-4:
        right = Vector((1, 0, 0))
    right.normalize()
    up = right.cross(fwd).normalized()
    return np.array(right), np.array(up)


def update_particles(t, shot, cs):
    right, up = cam_basis(cs)
    groups = {k: [] for k in MAXQ}
    for e in EMIT.get(shot, []):
        if e['t0'] <= t:
            groups[e['kind']].append(eval_emitter(e, t))
    camp, fwd = np.array(cs['loc']), np.array(cs['fwd'])
    for kind in MAXQ:
        ob, n = PART[kind], MAXQ[kind]
        V = np.zeros((n, 4, 3))
        C = np.zeros((n, 4, 4))
        if groups[kind]:
            pos, size, u, seed, alpha, glow = (np.concatenate(x) for x in zip(*groups[kind]))
            rel = pos - camp
            d = np.linalg.norm(rel, axis=1)
            front = rel @ fwd > 0.1
            pos, size, u, seed, alpha, glow, d = (a[front] for a in (pos, size, u, seed, alpha, glow, d))
            if kind == 'dot':
                size = size + 0.0012 * d
            if len(pos) > n:
                idx = np.argsort(d)[:n]
                pos, size, u, seed, alpha, glow, d = (a[idx] for a in (pos, size, u, seed, alpha, glow, d))
            m = len(pos)
            alpha = alpha * np.clip((d - size * 0.8) / (size * 1.5 + 0.2), 0, 1)
            rr, uu = right[None, :] * size[:, None], up[None, :] * size[:, None]
            V[:m] = np.stack([pos - rr - uu, pos + rr - uu, pos + rr + uu, pos - rr + uu], 1)
            C[:m] = np.stack([seed, u, glow, alpha], -1)[:, None, :]
        me = ob.data
        me.vertices.foreach_set('co', V.astype(np.float32).ravel())
        me.color_attributes['sm'].data.foreach_set('color', C.astype(np.float32).ravel())
        me.update()


def build_fx():
    FLY['bills'] = quad_mesh('FlyingBills', NBILLS, MAT['bill'], 'FX')
    for k in MAXQ:
        PART[k] = billboard_obj(k.capitalize(), MAXQ[k], MAT[k])


# ============================================================================
# Simple reach (IK-lite) and look-at helpers for the characters
# ============================================================================
def jmat(ob):
    M = ob.matrix_basis.copy()
    p = ob.parent
    while p is not None:
        M = p.matrix_basis @ M
        p = p.parent
    return M


def reach(name, side, target, bend=None):
    """Shoulder/elbow angles that put the hand (centre) at a world-space target. Returns (sh tuple, elbow)."""
    J = CH[name]['J']
    sh = J['sh' + side]
    M = jmat(J['chest']) @ Matrix.Translation(sh.location)
    d = M.inverted() @ Vector(target)
    D = d.length
    L = 0.59
    if bend is None:
        bend = math.degrees(2 * math.acos(min(D / L, 0.999))) if D < L else 6.0
        bend = max(bend, 6.0)
    dn = d.normalized()
    sw1 = math.asin(max(-1.0, min(1.0, dn.y)))
    ph1 = math.atan2(-dn.x, -dn.z)
    sw2 = math.pi - sw1
    ph2 = math.atan2(dn.x, dn.z)
    sw, ph = (sw1, ph1) if abs(ph1) <= abs(ph2) else (sw2, ph2)
    sg = -1 if side == 'R' else 1
    return (math.degrees(sw) - bend * 0.5, math.degrees(ph) * sg, 0.0), bend


def look_at(name, target, head=0.7):
    """Head turn/nod and eye angles toward a world-space point. Returns a pose fragment."""
    J = CH[name]['J']
    M = jmat(J['chest']) @ Matrix.Translation(J['neck'].location + HC)
    d = M.inverted() @ Vector(target)
    yaw = math.degrees(math.atan2(-d.x, d.y))
    pitch = math.degrees(math.atan2(d.z, math.hypot(d.x, d.y)))
    return dict(turn=yaw * head, nod=-pitch * head, look=(yaw * (1 - head) * 1.2, pitch * (1 - head) * 1.2))


def apply_reach(name, P, side, target, bend=None):
    pose(name, P)
    P['sh' + side], P['el' + side] = reach(name, side, target, bend)
    return P


# ============================================================================
# Cameras: one keyframed rig per shot (location, target, lens), bound with timeline markers
# ============================================================================
CAMS = {}
RIGS = {}
SHAKE = {}


def camera_shot(name, lens, path, target, fstop=8.0, shake=0.0, ease=True, lenses=None):
    """path/target: list of (u, (x, y, z)) keys with u in 0..1 of the shot. lenses: [(u, mm)]."""
    s = SHOT[name]
    rig = empty('Rig_' + name)
    tgt = empty('Target_' + name)
    cd = bpy.data.cameras.new('Cam_' + name)
    cd.lens = lens
    cd.sensor_width = 24
    cd.sensor_fit = 'VERTICAL'
    cd.clip_start, cd.clip_end = 0.02, 5000
    cd.dof.use_dof = fstop < 50
    cd.dof.aperture_fstop = fstop
    cd.dof.aperture_blades = 7
    cd.dof.focus_object = tgt
    cam = bpy.data.objects.new('Cam_' + name, cd)
    coll('Rig').objects.link(cam)
    cam.parent = rig
    con = rig.constraints.new('TRACK_TO')
    con.target = tgt
    con.track_axis = 'TRACK_NEGATIVE_Z'
    con.up_axis = 'UP_Y'
    span = s['f1'] + 1 - s['f0']
    for u, p in path:
        rig.location = p
        rig.keyframe_insert('location', frame=s['f0'] + u * span)
    for u, p in target:
        tgt.location = p
        tgt.keyframe_insert('location', frame=s['f0'] + u * span)
    if lenses:
        for u, mm in lenses:
            cd.lens = mm
            cd.keyframe_insert('lens', frame=s['f0'] + u * span)
    for idb in (rig, tgt, cd):
        if idb.animation_data:
            for fc in idb.animation_data.action.fcurves:
                for kp in fc.keyframe_points:
                    kp.interpolation = 'BEZIER'
                    kp.easing = ease if isinstance(ease, str) else ('EASE_IN_OUT' if ease else 'AUTO')
                    if not ease:
                        kp.handle_left_type = kp.handle_right_type = 'VECTOR'
    m = bpy.context.scene.timeline_markers.new('M_' + name, frame=s['f0'])
    m.camera = cam
    CAMS[name] = cam
    RIGS[name] = (rig, tgt, cd)
    SHAKE[name] = shake
    return cam


def eval_loc(ob, f):
    ad = ob.animation_data
    v = Vector(ob.location)
    if ad and ad.action:
        for fc in ad.action.fcurves:
            if fc.data_path == 'location':
                v[fc.array_index] = fc.evaluate(f)
    return v


def cam_state(name, f):
    rig, tgt, cd = RIGS[name]
    loc = eval_loc(rig, f)
    tl = eval_loc(tgt, f)
    return {'loc': tuple(loc), 'fwd': tuple((tl - loc).normalized())}


def shake_offset(t, name):
    amp = SHAKE.get(name, 0.0)
    if amp <= 0:
        return Vector((0, 0, 0))
    return Vector((math.sin(t * 7.0) + 0.5 * math.sin(t * 13.1), math.sin(t * 5.3 + 1), math.sin(t * 4.1 + 2))) * amp


