def chor_milk(t):
    store_background(t, 'milk')
    a, b = EV['flip_milk']
    g0, g1 = EV['gasp']
    P = merge(dict(loc=(-3.4, 31.36, 0), yaw=-12.0), idle(t, 3))
    u = ramp(t, g0, g1)
    P.update(blend_face(dict(smile=0.3, lid=0.15), SHOCK, u))
    pose('shopper', P)
    lk = look_at('shopper', STORE['tags']['milk0'].location, 0.6)
    lk2 = look_at('shopper', RIGS['milk'][0].location, 0.6)
    k = ramp(t, a, a + 0.15) * (1 - u)
    for kk in ('turn', 'nod'):
        P[kk] = lerp(lerp(0.0, lk[kk], k), lk2[kk], u)
    P['look'] = tuple(lerp(lerp(0.0, x, k), y, u) for x, y in zip(lk['look'], lk2['look']))
    P['lean'] = -6 * u
    if u <= 0:
        apply_reach('shopper', P, 'R', Vector((-3.3, 32.2, 1.12)))
    else:
        apply_reach('shopper', P, 'R', head_pt('shopper', (0.13, 0.05, -0.06)))
        apply_reach('shopper', P, 'L', head_pt('shopper', (-0.13, 0.05, -0.06)))
    pose('shopper', P)
    STORE['carts'][4].location = (-2.45, 30.75, 0)
    STORE['carts'][4].rotation_euler = (0, 0, R(15))
    for n in ('gary', 'cashier'):
        park(n)
    pose('owner', merge(dict(loc=(-1.85, 11.5, 0), yaw=90.0), idle(t)))


def chor_bike(t):
    store_background(t, 'bike')
    a, b = EV['flip_bike']
    u = ramp(t, a + 0.1, a + 0.35)
    P = merge(dict(loc=(8.95, 5.05, 0), yaw=67.0), idle(t, 5), blend_face(dict(smile=0.5), SHOCK, u))
    P['lean'] = -8 * u
    pose('bg1', P)
    P.update(look_at('bg1', STORE['tags']['bike0'].location, 0.6))
    pose('bg1', P)
    STORE['carts'][3].location = (9.7, 4.3, 0)
    STORE['carts'][3].rotation_euler = (0, 0, R(30))
    for n in ('gary', 'cashier', 'shopper'):
        park(n)
    pose('owner', merge(dict(loc=(-1.85, 11.5, 0), yaw=90.0), idle(t)))


def chor_count(t):
    store_background(t, 'count')
    P = merge(dict(loc=(-0.48, 1.7, 0), yaw=-90.0), WORRY, dict(nod=18 + 5 * math.sin(t * 9), side=3 * math.sin(t * 6)))
    pose('cashier', P)
    k = int(t * 5.5)
    rng = random.Random(k)
    for side, off in (('R', 0.0), ('L', 0.5)):
        kk = int(t * 5.5 + off)
        rr = random.Random(kk * 7 + (1 if side == 'R' else 2))
        tgt = Vector((rr.uniform(0.05, 0.3), rr.uniform(1.3, 2.3) if side == 'R' else rr.uniform(1.0, 1.9), rr.uniform(1.15, 1.45)))
        apply_reach('cashier', P, side, tgt)
    pose('cashier', P)
    n = int((t - 34.5) / 0.55)
    for i, d in enumerate(STORE['countdisp']):
        d.hide_render = (i != (3 if t > 36.5 else n % 3))
    park('gary')
    park('shopper', (-3.5, 31.3, 0))
    pose('owner', merge(dict(loc=(-1.85, 11.5, 0), yaw=90.0), idle(t)))


def chor_struggle(t):
    store_background(t, 'struggle')
    a, b = EV['eggs']
    P = merge(dict(loc=(-9.4, 31.4, 0), yaw=-10.0), idle(t, 3), WORRY, dict(lean=6))
    pose('shopper', P)
    eg = Vector((-9.6, 32.25, 1.49))
    u = ramp(t, 43.9, a)
    rest = chest_pt('shopper', (0.22, 0.2, -0.45))
    hold = chest_pt('shopper', (0.1, 0.45, -0.1))
    tgt = vlerp(vlerp(rest, eg, u), hold, ramp(t, a + 0.15, b))
    la, lb = look_at('shopper', eg, 0.6), look_at('shopper', RIGS['struggle'][0].location, 0.6)
    k = ramp(t, b - 0.2, b + 0.2)
    for kk in ('turn', 'nod'):
        P[kk] = lerp(la[kk], lb[kk], k)
    P['look'] = tuple(lerp(x, y, k) for x, y in zip(la['look'], lb['look']))
    apply_reach('shopper', P, 'R', tgt)
    pose('shopper', P)
    el = bpy.data.objects['EggLast']
    if t > a + 0.1:
        M = jmat(CH['shopper']['J']['elR'])
        el.location = M @ Vector((0, 0.06, -0.33)) - Vector((-9.6, 32.25, 1.45)) - Vector((0, 0, 0.04))
    else:
        el.location = (0, 0, 0)
    for k, x in enumerate((-8.9, -10.55)):
        STORE['carts'][k + 4].location = (x, 30.35, 0)
        STORE['carts'][k + 4].rotation_euler = (0, 0, R(180 + 10 * (k * 2 - 1)))
    for n in ('gary', 'cashier'):
        park(n)


def chor_final(t):
    PROPS['pile'].hide_render = True
    a, b = EV['card_flip2']
    P, mv = walk_along([(2.15, 9.6), (2.15, 4.0)], t, 50.3, 2.0, stride=1.4)
    P.update(dict(smile=0.9, brow=0.4, lid=0.0, nod=-4))
    bw = STORE['barrow']
    yaw = R(180.0)
    bw.location = (P['loc'][0], P['loc'][1] - 1.3, 0)
    bw.rotation_euler = (R(-4), 0, yaw)
    turn = 0.0
    P.update(dict(smile=1.0, brow=0.5, lid=0.0, look=(0, 3)))
    pose('gary', P)
    if turn < 0.5:
        M = bw.matrix_basis
        apply_reach('gary', P, 'R', M @ Vector((-0.28, -0.98, 0.64)))
        apply_reach('gary', P, 'L', M @ Vector((0.28, -0.98, 0.64)))
    else:
        P.update(look_at('gary', CARD_C, 0.6))
    pose('gary', P)
    card_state(t, 1, EV['card_flip2'])
    cashier_flip(t, EV['card_flip2'])
    store_background(t, 'final')
    pose('cash2', merge(dict(loc=(-4.5, 1.6, 0), yaw=-30.0), idle(t, 2), DEADPAN))
    pose('owner', merge(dict(loc=(-1.9, 12.0, 0), yaw=90.0), idle(t)))
    park('shopper', (-3.5, 31.3, 0))


def chor_stare(t):
    PROPS['pile'].hide_render = True
    a, b = EV['turn']
    u = ramp(t, a, b)
    f0, f1 = EV['face_fall2']
    face = blend_face(blend_face(GRIN, SHOCK, ramp(t, f0, f1)), DEADPAN, ramp(t, a - 0.1, a + 0.35))
    P = merge(dict(loc=tuple(GARY_AT), yaw=90.0), idle(t), face)
    pose('gary', P)
    lk1 = look_at('gary', CARD_C, 0.6)
    lk2 = look_at('gary', RIGS['stare'][0].location, 0.55)
    for k in ('turn', 'nod'):
        P[k] = lerp(lk1[k], lk2[k], u)
    P['look'] = tuple(lerp(x, y, u) for x, y in zip(lk1['look'], lk2['look']))
    P.update(shR=(5, 10, 0), shL=(5, 10, 0), elR=12, elL=12)
    if t > 55.55:
        P['brow'] = -0.1 + 0.35 * ramp(t, 55.6, 55.8)
        P['btilt'] = -0.6 * ramp(t, 55.6, 55.8)
    pose('gary', P)
    card_state(t, 1, EV['card_flip2'])
    cashier_flip(t, EV['card_flip2'])
    STORE['barrow'].location = (2.3, 2.3, 0)
    STORE['barrow'].rotation_euler = (R(-4), 0, R(160))
    store_background(t, 'stare')


def chor_tagend(t):
    chor_stare(t)


