def build_emitters():
    rng = np.random.default_rng(3)
    # store: dust motes in the light, notes slipping off the customer's pile, the counting machine
    sd = [(rng.uniform(-3, 3.5), rng.uniform(-1, 14), rng.uniform(0.5, 3.5)) for _ in range(160)]
    md = [(rng.uniform(-12, -1), rng.uniform(28, 32), rng.uniform(0.5, 3.0)) for _ in range(80)]
    for nm in ('hook_a', 'hook_b', 'hook_c', 'store', 'tags', 'bike', 'count', 'final', 'stare', 'tagend'):
        EMIT[nm] = [emitter('dot', sd, 0.25, 16.0, (0.01, 0.0, -0.01), 0.01, (0.004, 0.007), opacity=0.5, area=1.0, t0=-16.0, turb=0.15, salt=1)]
    for nm in ('milk', 'struggle'):
        EMIT[nm] = [emitter('dot', md, 0.25, 16.0, (0.01, 0.0, -0.01), 0.01, (0.004, 0.007), opacity=0.5, area=1.0, t0=-16.0, turb=0.15, salt=2)]
    gy = lambda tb: 7.6 - 1.7 * min(max(tb, 0.0), 2.76)
    BEMIT['hook_a'] = [bill_emitter(lambda tb: Vector((1.35, gy(tb) - 0.38, 1.6)), 2.2, 2.0, t0=0.2, area=(0.18, 0.08, 0.05),
                                    v0=(0, -0.6, 0.3), fall=0.8, ground=0.0, salt=1)]
    BEMIT['count'] = [bill_emitter([(0.38, 2.9, 1.2)], 9.0, 1.8, t0=33.5, area=(0.03, 0.08, 0.02), v0=(-1.4, 0.0, 2.2), vjit=0.6,
                                   fall=1.0, tau=0.5, ground=0.93, salt=2, spin=6.0)]
    # suburb: notes rain from the canopy
    cp = tree_points('MoneyTree', 120, 4)
    BEMIT['tree'] = [bill_emitter(cp, 0.25, 4.0, t0=8.25, fall=0.85, flutter=0.3, ground=SUB.z + 0.03, salt=3, area=(0.2, 0.2, 0.1), scale=1.45)]
    BEMIT['crowd'] = [bill_emitter(cp, 0.8, 5.0, t0=7.0, fall=0.9, flutter=0.3, ground=SUB.z + 0.03, salt=4, area=(0.2, 0.2, 0.1), scale=1.45)]
    cpg = tree_points('GiantTree', 400, 6)
    BEMIT['giant'] = [bill_emitter(cpg, 0.06, 18.0, t0=20.0, fall=1.0, flutter=0.6, ground=SUB.z + 0.03, salt=5, area=(0.5, 0.5, 0.2),
                                   scale=1.3)]
    sub = [tuple(S(rng.uniform(-6, 3), rng.uniform(2, 10), rng.uniform(0.5, 5))) for _ in range(120)]
    for nm in ('bill', 'tree', 'crowd', 'giant'):
        EMIT[nm] = [emitter('dot', sub, 0.2, 18.0, (0.05, 0.02, 0.0), 0.02, (0.006, 0.012), opacity=0.45, area=1.5, t0=-18.0, turb=0.2, salt=6)]
    # farm: dust in the low sun; the leaf blower's river of notes
    fd = [tuple(Fm(rng.uniform(-4, 4), rng.uniform(0, 8), rng.uniform(0.2, 2.5))) for _ in range(60)]
    EMIT['farmer'] = [emitter('dust', fd, 0.15, 12.0, (0.3, 0.1, 0.02), 0.05, (0.3, 0.9), opacity=0.12, area=2.0, t0=-12.0, turb=0.4, salt=7)]
    BEMIT['farm'] = [bill_emitter(blower_src, 60.0, 2.2, t0=17.0, v0=(-6.5, 1.6, 0.6), vjit=1.2, fall=0.7, tau=0.45, flutter=0.3,
                                  ground=FARM.z + 0.05, salt=8, scale=1.2, spin=5.0, area=(0.05, 0.05, 0.05))]
    fod = [tuple(FOREST + Vector((rng.uniform(-8, 8), rng.uniform(-3, 20), FORD['z0'] + rng.uniform(0.5, 8)))) for _ in range(120)]
    EMIT['forest'] = [emitter('dot', fod, 0.2, 18.0, (0.1, 0.05, 0.02), 0.02, (0.01, 0.02), opacity=0.4, area=2.0, t0=-18.0, turb=0.3, salt=9)]
    BEMIT['forest'] = [bill_emitter([tuple(FOREST + Vector((0, 10, FORD['z0'] + 6)))], 14.0, 9.0, t0=12.0, area=(9, 6, 3), fall=0.5,
                                    wind=(0.6, -0.3, 0), flutter=0.5, ground=-1e9, salt=10, scale=1.3)]
    # city: a blizzard of notes blowing down the street toward the camera
    BEMIT['city'] = [bill_emitter([tuple(Ct(0.0, 60.0, 7.0))], 140.0, 26.0, t0=0.0, area=(10.5, 50.0, 6.5), fall=0.25,
                                  wind=(0.8, -3.2, 0.0), flutter=0.6, ffreq=2.0, spin=3.0, ground=CITY.z + 0.04, salt=11, scale=1.25)]
    BEMIT['graph'] = BEMIT['city']


